/* Explicit user-run GPU tests; no external dependencies or response-storage access. */
(()=>{const button=document.getElementById('run'),report=document.getElementById('report'),wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));button.addEventListener('click',async()=>{button.disabled=true;report.textContent='';let passed=0,failed=0;const check=(v,m)=>{if(!v)throw Error(m);};try{const response=await fetch('catalog.json');if(!response.ok)throw Error('Local catalog missing');const c=await response.json();for(const d of c.destinations){let scene;try{const a=Object.fromEntries(c.questions.map((q,i)=>[q.id,d.affinities[i][0].toLowerCase()]));scene=DestinationExperience.open(c,a,{id:d.id,motion:false});await wait(100);if(d.id==='paris'){const deadline=Date.now()+15000;while(!scene.state().quality&&Date.now()<deadline)await wait(100);check(scene.state().quality,'Imported Eiffel asset did not activate; original blockout is not a passing quality test');}const dialog=document.querySelector('.destination-experience');check(dialog.querySelectorAll('.destination-days article').length===3,'Three-day itinerary missing');if(DestinationModels.definitions[d.id]){const first=scene.inspect();check(first&&first.error===0&&first.nonBackgroundPixels>500,'No valid rendered WebGL environment');dialog.querySelector('.destination-stops button').click();await wait(100);check(scene.inspect().hash!==first.hash,'Attraction camera did not change pixels');check(scene.state().selected===0,'Attraction selection missing');check(dialog.scrollWidth<=innerWidth+2,'Horizontal overflow');}else check(!scene.state().ready,'Fallback incorrectly marked immersive');passed++;report.textContent+=`PASS ${d.name}\n`;}catch(e){failed++;report.textContent+=`FAIL ${d.name}: ${e.message}\n`;}finally{scene?.close();await wait(30);}}}catch(e){failed++;report.textContent+=`SETUP FAILED: ${e.message}\n`;}finally{report.textContent+=`\n${passed} passed; ${failed} failed.\n`;button.disabled=false;}});})();
